import re

def recover_inventory(connection):
    with connection.cursor()as cursor:
        cursor.execute('XA RECOVER CONVERT XID');rows=cursor.fetchall()
    inventory=[]
    for fmt,glen,blen,data in rows:
        if type(fmt)is not int or type(glen)is not int or type(blen)is not int or not 1<=glen<=64 or not 0<=blen<=64:raise ValueError('native XA inventory framing')
        encoded=data.decode('ascii')if isinstance(data,bytes)else data
        if not isinstance(encoded,str)or not re.fullmatch(r'0x[0-9A-Fa-f]+',encoded):raise ValueError('native XA hex framing')
        raw=bytes.fromhex(encoded[2:])
        if len(raw)!=glen+blen:raise ValueError('native XA length differs')
        inventory.append({'format_id':fmt,'gtrid_hex':raw[:glen].hex(),'bqual_hex':raw[glen:].hex()})
    return sorted(inventory,key=lambda row:(row['format_id'],row['gtrid_hex'],row['bqual_hex']))

def resolve(connection,decisions):
    if not isinstance(decisions,dict)or any(not isinstance(xid,str)or not re.fullmatch(r'of_[a-z0-9_]{1,60}',xid)or action not in('commit','rollback','unknown')for xid,action in decisions.items()):raise ValueError('trusted literal decision set required')
    prepared={row['gtrid_hex']for row in recover_inventory(connection)if row['format_id']==1 and row['bqual_hex']==''}
    result={}
    with connection.cursor()as cursor:
        for xid,action in decisions.items():
            if xid.encode('ascii').hex()not in prepared:result[xid]='not_prepared'
            elif action=='unknown':result[xid]='pending'
            else:cursor.execute('XA '+action.upper()+' %s',(xid,));result[xid]=action
    return result

