import os,pathlib,tempfile,hashlib,json
import task as t

def export_snapshot(connection,plan,directory,checkpoint=None):
    t.validate_plan(plan);path=t.directory(directory)
    if checkpoint is not None and not callable(checkpoint):raise ValueError('callable checkpoint required')
    with t.borrowed(connection,plan['source_uuid'],True):
        if path.exists():
            manifest,_=t.load_bundle(plan,path);return manifest
        metadata=t.catalog(connection)
        if t.digest(metadata)!=plan['catalog_sha256']:raise ValueError('approved source schema differs')
        path.parent.mkdir(parents=True,exist_ok=True)
        with tempfile.TemporaryDirectory(prefix='.gipk-export-',dir=str(path.parent))as staging:
            stage=pathlib.Path(staging);files={};total=0;size=0
            for table in t.TABLES:
                records=t.rows(connection,table,metadata[table]);raw=b''.join(t.canonical(row)+b'\n'for row in records)
                total+=len(records);size+=len(raw)
                if total>plan['max_rows']or size>plan['max_bytes']:raise ValueError('snapshot budget exceeded')
                target=stage/(table+'.jsonl')
                with target.open('xb')as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
                files[table]={'name':target.name,'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'rows':len(records)}
                if checkpoint is not None:checkpoint('after_table',table)
            manifest={'schema':1,'plan_sha256':t.digest(plan),'catalog':metadata,'files':files,'total_rows':total,'total_bytes':size}
            t.publish(stage/'manifest.json',manifest);t.load_bundle(plan,stage)
            if checkpoint is not None:checkpoint('before_publish',None)
            path.mkdir()
            for table in t.TABLES:os.link(stage/files[table]['name'],path/files[table]['name'])
            os.link(stage/'manifest.json',path/'manifest.json')
            if checkpoint is not None:checkpoint('after_publish',None)
            return manifest

