"""Teacher-only observation of successful file synchronization, not directory durability."""
import os,pathlib,hashlib,stat
ROOT=None
ACTIVE=False
SYNCED=set()
NAMES={'manifest.json','report.json','failure.json','gipk_probe.jsonl','composite_probe.jsonl','linked_probe.jsonl'}
def state(path):
 path=pathlib.Path(path)
 if not path.is_file()or path.is_symlink():return None
 info=path.stat();return(info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns,hashlib.sha256(path.read_bytes()).hexdigest())
def ours(path):
 if ROOT is None:return False
 try:pathlib.Path(path).absolute().relative_to(ROOT)
 except ValueError:return False
 return True
def install():
 for name in('fsync','fdatasync'):
  original=getattr(os,name)
  def observed(fd,_original=original):
   result=_original(fd)
   try:
    info=os.fstat(fd)
    # Observe only this successful call's actual owned regular FD. Do not require staging beside ROOT or scan outside paths.
    if ACTIVE and stat.S_ISREG(info.st_mode)and info.st_uid==os.geteuid():
     with open('/proc/self/fd/'+str(fd),'rb')as stream:
      current=os.fstat(stream.fileno())
      if(current.st_dev,current.st_ino)==(info.st_dev,info.st_ino):SYNCED.add((current.st_dev,current.st_ino,current.st_size,current.st_mtime_ns,hashlib.sha256(stream.read()).hexdigest()))
   except OSError:pass
   return result
  setattr(os,name,observed)
 for name in('link','rename','replace'):
  original=getattr(os,name)
  def observed(source,destination,*args,_original=original,**kwargs):
   if ACTIVE and ours(destination)and pathlib.Path(source).is_dir():
    for file in pathlib.Path(source).rglob('*'):
     if file.name in NAMES and file.is_file():assert state(file)in SYNCED,'directory publication preceded actual synchronization of current artifact bytes'
   if ACTIVE and ours(destination)and pathlib.Path(destination).name in NAMES and pathlib.Path(source).is_file():
    assert state(source)in SYNCED,'published file current bytes were not actually synchronized before publication'
   return _original(source,destination,*args,**kwargs)
  setattr(os,name,observed)
def capture(directory):
 path=pathlib.Path(directory)
 return{file.name:state(file)for file in path.iterdir()if file.name in NAMES and file.is_file()}if path.exists()else{}
def require(directory,before):
 path=pathlib.Path(directory)
 if not path.exists():return
 for file in path.iterdir():
  if file.name in NAMES and file.is_file()and before.get(file.name)!=state(file):assert state(file)in SYNCED,'new/changed returned artifact current bytes were not actually file-synchronized'

