 if ansi_quotes:statement=re.sub(r'"([^"]*)"',lambda match:' '+match[1]+' ',statement)
 else:statement=re.sub(r'"(?:""|\\.|[^"])*"',' ',statement)
 statement=re.sub(r'/\*.*?\*/|--[^\n]*|#[^\n]*',' ',statement,flags=re.S)
 statement=re.sub(r'`([^`]*)`',lambda match:' '+match[1]+' ',statement)
 if not re.match(r'^\s*(?:\(\s*)*(?:SELECT|WITH|TABLE)\b',statement,re.I):return False
 return bool(re.search(r'\b(?:FROM|JOIN)\s+(?:training\s*\.\s*)?(?:gipk_probe|composite_probe|linked_probe)\b',statement,re.I)or re.match(r'^\s*TABLE\s+(?:training\s*\.\s*)?(?:gipk_probe|composite_probe|linked_probe)\b',statement,re.I))
